#!/usr/bin/env python3
from __future__ import annotations

"""Stage equation-preserving numerical core V3.1 into an isolated worktree.

V3.1 is deliberately narrow: it closes the three red gates from the first V3
run without changing the scientific equations or the project's compatibility
thresholds.
"""

import argparse
import base64
import hashlib
import json
from pathlib import Path
import subprocess

EXPECTED_BRANCH = 'science/universal-validation-recovered'
EXPECTED_BLOBS = {'src/cualni_cryst/ball_james.py': '5ffafe7e3e14725d8e8a634c1165d9c00e0b1c60',
 'src/cualni_cryst/ct.py': '213ca06c283a0419a37554e0344daec86e258536',
 'src/cualni_cryst/james_hane.py': '967d33f7f36678b37f836ef1aa37f5c85dace81a',
 'src/cualni_cryst/lattice.py': '56f5b222ea5c722a4c6c9ca8dfba041c78b38d05',
 'src/cualni_cryst/ptmc.py': '7e0cd63c346fe79ffddef45ab698bdff5b2f046c',
 'src/cualni_cryst/rank_one.py': '4c01d105aca2bd1bfd36b76e0e96be17e1c18990',
 'src/cualni_cryst/stretch.py': '4d6612c49598813f7fcbcabc6c2c7f8e7cde6bc0',
 'tests/test_engineered_ct_generalized_vs_whitened.py': '315e886934bffdeb955744b6a2e4ccce031ca244',
 'tests/test_engineered_high_precision_conditioning.py': '6f8b98cc8219520f4ce161627fe04730d41a0c6a',
 'tests/test_engineered_metamorphic.py': 'dcfe6bb38e3a629bd0497cd2de72db786ca6eddf',
 'tools/run_engineered_falsification_v2.py': '6fcc7f25ac514e0c0394424b07417492122e3bdf',
 'validation/engineered/harness.py': '243776a41cd342e2db8b503de10c6b38a5f616c7',
 'validation/engineered/high_precision.py': '22b465517c6fc55bdfdedb31a754b64ff25486f2',
 'validation/engineered/metamorphic.py': '281dbf4be4188695237540b05d9451e24b9b6017',
 'validation/engineered/production.py': '2aff95886f585d6a3780c81cb22e068838bcf0e4',
 'validation/engineered/ptmc_oracle.py': '37b57b234c087f99202842789b9c365d8c1e779f'}
PAYLOADS_B64 = {'docs/NUMERICAL_CORE_V3.md': '',
 'src/cualni_cryst/adaptive_metric.py': '',
 'src/cualni_cryst/ball_james.py': '',
 'src/cualni_cryst/ct.py': '',
 'src/cualni_cryst/lattice.py': '',
 'src/cualni_cryst/ptmc.py': '',
 'src/cualni_cryst/rank_one.py': '',
 'src/cualni_cryst/stretch.py': '',
 'tests/test_engineered_ct_generalized_vs_whitened.py': '',
 'tests/test_engineered_high_precision_conditioning.py': '',
 'tests/test_engineered_metamorphic.py': '',
 'tests/test_equation_preserving_adaptive_core_v3.py': '',
 'tools/run_engineered_falsification_v2.py': '',
 'validation/engineered/certified_binary64.py': '',
 'validation/engineered/harness.py': '',
 'validation/engineered/high_precision.py': '',
 'validation/engineered/metamorphic.py': '',
 'validation/engineered/production.py': '',
 'validation/engineered/ptmc_oracle.py': ''}
JAMES_HANE_OLD = '    if rhs < -1e-12 or rhs > 1+1e-12:\n        raise ValueError(f"No real exact-compatibility beta for rhs={rhs}")\n    rhs = min(1.0,max(0.0,rhs))\n'
JAMES_HANE_NEW = '    # Only a machine-roundoff guard is allowed at the acos domain edge.\n    # A genuinely out-of-domain rhs is not silently projected into [0,1].\n    edge_tol = 64.0 * np.finfo(float).eps\n    if rhs < -edge_tol or rhs > 1.0 + edge_tol:\n        raise ValueError(f"No real exact-compatibility beta for rhs={rhs}")\n    if rhs < 0.0:\n        rhs = 0.0\n    elif rhs > 1.0:\n        rhs = 1.0\n'


def run(repo: Path, *args: str, check: bool = True) -> subprocess.CompletedProcess[str]:
    p = subprocess.run(
        list(args), cwd=repo, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE
    )
    if check and p.returncode != 0:
        raise RuntimeError("command failed: " + " ".join(args) + "\n" + p.stdout + p.stderr)
    return p


def git_blob_sha(repo: Path, rel: str) -> str:
    return run(repo, "git", "hash-object", rel).stdout.strip()


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected exactly one source match, found {count}")
    return text.replace(old, new, 1)


def preflight(repo: Path) -> None:
    branch = run(repo, "git", "branch", "--show-current").stdout.strip()
    if branch != EXPECTED_BRANCH:
        raise RuntimeError(f"wrong branch: {branch!r}; expected {EXPECTED_BRANCH!r}")

    bad = {}
    for rel, expected in EXPECTED_BLOBS.items():
        path = repo / rel
        if not path.is_file():
            bad[rel] = {"expected": expected, "actual": "MISSING"}
            continue
        actual = git_blob_sha(repo, rel)
        if actual != expected:
            bad[rel] = {"expected": expected, "actual": actual}
    if bad:
        raise RuntimeError(
            "Refusing to apply V3.1 on an unexpected scientific state. "
            "No source file was changed. Blob mismatches:\n"
            + json.dumps(bad, indent=2, sort_keys=True)
        )

    for rel in EXPECTED_BLOBS:
        p = run(repo, "git", "diff", "--quiet", "HEAD", "--", rel, check=False)
        if p.returncode != 0:
            raise RuntimeError(
                f"{rel} already has uncommitted changes; refusing to stack repairs"
            )

    # Files introduced by the gated installer must still be absent in the
    # submitted branch.  This prevents silently layering V3.1 over a partial
    # hand-applied V3 tree.
    introduced = sorted(set(PAYLOADS_B64) - set(EXPECTED_BLOBS))
    present = [rel for rel in introduced if (repo / rel).exists()]
    if present:
        raise RuntimeError(
            "Refusing to overwrite files that should only exist in the isolated "
            "generated tree. Remove partial hand-applied V3 files first: "
            + ", ".join(present)
        )


def write_payloads(repo: Path) -> list[str]:
    written = []
    for rel, encoded in PAYLOADS_B64.items():
        path = repo / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode(encoded))
        written.append(rel)
    return written


def patch_james_hane(repo: Path) -> str:
    rel = "src/cualni_cryst/james_hane.py"
    path = repo / rel
    text = path.read_text(encoding="utf-8")
    text = replace_once(text, JAMES_HANE_OLD, JAMES_HANE_NEW, "James-Hane Eq.25 domain guard")
    path.write_text(text, encoding="utf-8")
    return rel


def source_guards(repo: Path) -> None:
    ct = (repo / "src/cualni_cryst/ct.py").read_text(encoding="utf-8")
    required_ct = [
        "A = C.T @ M_m @ C - M_a\n    return A",
        "G = W @ (C.T @ M_m @ C) @ W",
        "return adaptive_smc(M_a, M_m, C)",
        "np.sqrt(vals[ip]) * V[:, ip]",
    ]
    missing = [x for x in required_ct if x not in ct]
    if missing:
        raise RuntimeError(f"equation-preservation source guard failed: {missing}")

    adaptive = (repo / "src/cualni_cryst/adaptive_metric.py").read_text(encoding="utf-8")
    required_adaptive = [
        "return np.asarray(C, float).T @ np.asarray(M_m, float) @ np.asarray(C, float)",
        "def _exact_spd_binary64(",
        "leading-principal-minor signs",
        "M_a^-1 - (C.T M_m C)^-1",
        "return high_precision_smc(M_a, M_m, C, digits=digits)",
    ]
    missing = [x for x in required_adaptive if x not in adaptive]
    if missing:
        raise RuntimeError(f"adaptive-kernel source guard failed: {missing}")

    oracle = (repo / "validation/engineered/certified_binary64.py").read_text(
        encoding="utf-8"
    )
    required_oracle = [
        "float(x).as_integer_ratio()",
        "def exact_canonical_metric_spd(",
        "Xi * (M ** -1) * Xi.T",
        "gamma_3",
    ]
    missing = [x for x in required_oracle if x not in oracle]
    if missing:
        raise RuntimeError(f"independent-oracle source guard failed: {missing}")

    meta = (repo / "validation/engineered/metamorphic.py").read_text(encoding="utf-8")
    required_meta = [
        "P_1 - T(P_0)",
        "decomposition_bound_abs",
        "oracle_encoding_drift_abs",
        "lambda_decomposition_ratio",
    ]
    missing = [x for x in required_meta if x not in meta]
    if missing:
        raise RuntimeError(f"metamorphic-decomposition source guard failed: {missing}")

    cofactor = (repo / "src/cualni_cryst/cofactor.py").read_text(
        encoding="utf-8"
    ).replace(" ", "")
    if "np.trace(U2)-np.linalg.det(U2)-0.25" not in cofactor:
        raise RuntimeError("cofactor CC3 minus-det source guard failed")

    ptmc = (repo / "src/cualni_cryst/ptmc.py").read_text(encoding="utf-8")
    if (
        "hidden\n    ``1e-6`` acceptance is removed" not in ptmc
        and "hidden ``1e-6`` acceptance is removed" not in ptmc
    ):
        raise RuntimeError("PTMC hidden-tolerance guard missing")


def compile_changed(repo: Path, paths: list[str]) -> None:
    failures = []
    for rel in paths:
        path = repo / rel
        if path.suffix != ".py":
            continue
        try:
            compile(path.read_text(encoding="utf-8"), rel, "exec")
        except Exception as exc:
            failures.append({"path": rel, "error": repr(exc)})
    if failures:
        raise RuntimeError(
            "generated Python did not compile:\n" + json.dumps(failures, indent=2)
        )


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", default=".")
    args = ap.parse_args()
    repo = Path(args.repo).resolve()

    preflight(repo)
    written = write_payloads(repo)
    written.append(patch_james_hane(repo))
    source_guards(repo)
    compile_changed(repo, written)

    diff_check = run(repo, "git", "diff", "--check", check=False)
    if diff_check.returncode != 0:
        raise RuntimeError(
            "git diff --check failed:\n" + diff_check.stdout + diff_check.stderr
        )

    manifest = {}
    for rel in sorted(set(written)):
        manifest[rel] = hashlib.sha256((repo / rel).read_bytes()).hexdigest()
    out = Path("/tmp/equation_preserving_v3_install_manifest.json")
    out.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )

    print("V3.1 generated source installed into the Actions working tree.")
    print("Scientific compatibility tolerance changed: NO")
    print("CMC equation changed: NO")
    print("CMC literal post-symmetrization removed: YES")
    print("SMC definition changed: NO")
    print("SMC arithmetic promoted to high precision: YES")
    print("Exact canonical SPD certification added: YES")
    print("Metamorphic fixed thresholds replaced by error decomposition: YES")
    print("Ball-James theorem/formulas changed: NO")
    print("PTMC determinant equation changed: NO")
    print("manifest:", out)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
